/**
 * @author Vitaliy Fedoriv
 */

@RestController
@CrossOrigin(exposedHeaders = "errors, content-type")
@RequestMapping("/api")
public class OwnerRestControllerV1 implements OwnersApi {

    /** Dedicated audit logger; emits one line per successful owner create. */
    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    /**
     * Process-wide, monotonically increasing sequence stamped onto each structured
     * {@code OWNER_CREATED} audit event so consumers can order and de-duplicate them.
     */
    private static final AtomicLong AUDIT_EVENT_SEQ = new AtomicLong();

    /** Serializes structured audit events to compact JSON. */
    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    private final PetMapper petMapper;

    private final VisitMapper visitMapper;

    /** HTTP header carrying the caller-supplied idempotency key for owner creates. */
    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";

    /**
     * Records the owner created for each previously-seen idempotency key, so a create that repeats a
     * key returns the originally created owner instead of creating a duplicate. Keyed by the raw
     * header value; the stored value is the response returned for the first successful create.
     */
    private final Map<String, OwnerDto> idempotentCreations = new ConcurrentHashMap<>();

    public OwnerRestControllerV1(ClinicService clinicService,
                                 OwnerMapper ownerMapper,
                                 PetMapper petMapper,
                                 VisitMapper visitMapper) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
        // Idempotent create: when the request carries an 'Idempotency-Key' header that we have already
        // seen, return the owner originally created for that key with 200 instead of creating a
        // duplicate (which would otherwise be rejected as a 409 conflict). A brand-new key is recorded
        // below once the create succeeds; a request without the header is never treated as idempotent.
        String idempotencyKey = currentIdempotencyKey();
        if (idempotencyKey != null) {
            OwnerDto existing = idempotentCreations.get(idempotencyKey);
            if (existing != null) {
                return new ResponseEntity<>(existing, HttpStatus.OK);
            }
        }
        // Normalize the address up front so every downstream use (the required-field check,
        // household-duplicate detection, the shared household id and the stored/returned value)
        // works from the same canonical form. The structured 'addressLine1'/'addressLine2' fields are
        // preferred when present; the flat 'address' remains accepted for backward compatibility. Each
        // supplied line is normalized the same way, and the composed address is the normalized
        // addressLine1 with a single space and the normalized addressLine2 appended when present.
        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
        boolean structuredAddress = !isBlank(normalizedAddressLine1);
        String normalizedAddress;
        if (structuredAddress) {
            normalizedAddress = normalizedAddressLine2.isEmpty()
                ? normalizedAddressLine1
                : normalizedAddressLine1 + " " + normalizedAddressLine2;
        } else {
            normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
        }
        List<String> missingFields = new ArrayList<>();
        if (isBlank(ownerFieldsDto.getFirstName())) {
            missingFields.add("firstName");
        }
        if (isBlank(ownerFieldsDto.getLastName())) {
            missingFields.add("lastName");
        }
        // Reject an address that is blank once normalized (e.g. whitespace-only input).
        if (isBlank(normalizedAddress)) {
            missingFields.add("address");
        }
        if (isBlank(ownerFieldsDto.getCity())) {
            missingFields.add("city");
        }
        if (isBlank(ownerFieldsDto.getTelephone())) {
            missingFields.add("telephone");
        }
        if (!missingFields.isEmpty()) {
            throw new InvalidOwnerFieldsException(missingFields);
        }
        // A supplied registration date may not lie in the future: reject with 400 when the caller
        // provides a date later than the server's current date. Checked against the raw supplied value
        // (before any business-day adjustment) so a future date is never silently accepted.
        if (ownerFieldsDto.getRegistrationDate() != null
            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
            throw new FutureRegistrationDateException(ownerFieldsDto.getRegistrationDate());
        }
        // Determine the effective registration date up front so every downstream use (the daily
        // create-limit, the stored value and anything derived from it such as the membership number's
        // year segment) works from the same business-day-adjusted date. The effective date is the
        // supplied value when present, otherwise the server's current date; a weekend date is rolled
        // forward to the following Monday.
        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
            ? ownerFieldsDto.getRegistrationDate()
            : LocalDate.now();
        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
        // already carry this adjusted business day's registration date, no further owners may be
        // created for that day.
        int ownersRegisteredToday = countOwnersRegisteredOn(effectiveRegistrationDate);
        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
        }
        // Flag a bulk signup once more than 80 owners have already been created for this
        // business day, sharing the same daily accumulation path as the create-limit rule above.
        boolean bulkSignupWarning = ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD;
        // Reject the request when the owner's city is already full: a city that already holds the
        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
        int ownersInCity = countOwnersInCity(ownerFieldsDto.getCity());
        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
            throw new CityAtCapacityException(ownerFieldsDto.getCity());
        }
        // Flag a capacity warning when the owner's city is approaching the per-city limit: it already
        // holds between 40 and 49 owners (the hard rejection at 50 above is unchanged).
        boolean capacityWarning = ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD;
        // Postcode is optional; when present it must be a 4-digit value that is valid for the
        // owner's city per the fixed region ranges. A malformed or out-of-range postcode is
        // rejected with a 400. An absent postcode leaves the request contract unchanged.
        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
        // Normalize the telephone into E.164 form; a number that cannot form a valid
        // E.164 value is rejected with a 400.
        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
        // Email is optional; when present it must be a syntactically valid address and is
        // stored lower-cased. An invalid address is rejected with a 400.
        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
        // Derive the household id up front. It is a deterministic function of the normalized last name
        // and the postcode, so owners sharing a last name and postcode independently derive the same
        // value and are the same household. It is always computed (never null), regardless of whether
        // the caller opts into a shared household; 'sharesHousehold' now only bypasses the household
        // duplicate block below.
        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
        String householdId = householdId(normalizedLastName, ownerFieldsDto.getPostcode());
        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
        // All duplicate detection is consolidated into a single derived identity key: the SHA-256 hex
        // over 'normalizedTelephone + | + lowerEmail + | + soundex(lastName)'. Because the telephone is
        // part of the key, two members of the same household (same last name and postcode) with
        // different telephones have different keys and are both allowed; only an exact whole-key match
        // is a duplicate. The email-domain blocklist has already been applied (during email
        // normalization above). Reject with 409 when a new owner's whole identity key equals an
        // existing (non-deleted) owner's. The computed householdId no longer contributes a separate
        // duplicate block; it is retained only for household grouping (size, level cap, points).
        String identityKey = identityKey(normalizedTelephone, normalizedEmail, ownerFieldsDto.getLastName());
        boolean identityInUse = this.clinicService.findAllOwners().stream()
            .filter(existing -> !existing.isDeleted())
            .anyMatch(existing -> identityKey.equals(
                identityKey(existing.getTelephone(), existing.getEmail(), existing.getLastName())));
        if (identityInUse) {
            throw new DuplicateOwnerIdentityException(identityKey);
        }
        HttpHeaders headers = new HttpHeaders();
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        // Store the composed, normalized address plus the normalized structured lines. The structured
        // lines are only retained when the owner was supplied in the structured form; a flat-address
        // owner keeps them null.
        owner.setAddress(normalizedAddress);
        owner.setAddressLine1(structuredAddress ? normalizedAddressLine1 : null);
        owner.setAddressLine2(structuredAddress && !normalizedAddressLine2.isEmpty()
            ? normalizedAddressLine2 : null);
        owner.setTelephone(normalizedTelephone);
        owner.setEmail(normalizedEmail);
        owner.setHouseholdId(householdId);
        // Record how many existing owners (before this create) share this owner's first and last
        // name, compared case-insensitively. Computed against the current owners so the new owner
        // itself is never counted.
        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
        // Record the size of this owner's household (owners sharing the same householdId) after this
        // create: the existing members already stamped with the shared identifier plus this new
        // owner. An owner not admitted into any household is a household of one.
        owner.setHouseholdSize(countHouseholdMembers(householdId) + 1);
        // Cap the new owner's membership level at one above the current maximum membership level
        // among their existing household members (members already carrying this household id). The cap
        // applies to an owner joining an existing household on their own; an explicitly declared
        // 'sharesHousehold' member keeps its full points-based level. When there is no existing
        // household member, no cap applies and the level is left uncapped.
        owner.setMembershipLevelCap(sharesHousehold ? null : householdMembershipLevelCap(householdId));
        // Persist the bulk-signup flag computed above so it is returned on subsequent reads.
        owner.setBulkSignupWarning(bulkSignupWarning);
        // Persist the capacity-warning flag computed above so it is returned on subsequent reads.
        owner.setCapacityWarning(capacityWarning);
        // Store the business-day-adjusted effective registration date computed above. This defaults
        // to the server's current date when none was supplied and rolls any weekend date forward to
        // the following Monday, so everything derived from it (e.g. the membership number's year
        // segment) uses the adjusted date.
        owner.setRegistrationDate(effectiveRegistrationDate);
        // Assign the unified member id: '<REGION><FY><HASH8><CHK>' where REGION is the region derived
        // from the owner's postcode (falling back to the city-to-region table, else 'UNKNOWN', matching
        // the locality derivation), FY is the 2-digit fiscal year of the (already business-day-adjusted)
        // registration date, HASH8 is the first 8 upper-case hex characters of
        // SHA-256(normalizedTelephone + lastName), and CHK is a single Luhn check digit over the digits
        // of '<REGION><FY><HASH8>'. Compute the base value, then de-duplicate it: if it collides with an
        // existing owner's memberId, append '-<n>' using the smallest n of 2 or more that yields a value
        // no existing owner already carries.
        owner.setMemberId(deduplicateMemberId(memberId(
            deriveRegion(owner.getPostcode(), owner.getCity()),
            effectiveRegistrationDate, normalizedTelephone, owner.getLastName())));
        // Soft-match detection: an owner that cleared the hard-duplicate check above may still
        // resemble an existing owner when its identity key differs but it shares that owner's
        // soundex(lastName) and postcode (a different telephone, and now a same-household-but-distinct
        // registration, both land here rather than being rejected). A declared household member
        // ('sharesHousehold') is never a suspected duplicate, so it is exempt. Flag a matched owner as
        // a possible duplicate, recording its id; otherwise the flag is false with no matched id.
        Owner possibleDuplicateOwner = sharesHousehold ? null : findPossibleDuplicate(
            owner.getLastName(), owner.getPostcode(), identityKey);
        owner.setPossibleDuplicate(possibleDuplicateOwner != null);
        owner.setPossibleDuplicateOf(possibleDuplicateOwner == null ? null : possibleDuplicateOwner.getId());
        this.clinicService.saveOwner(owner);
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
        // member id, the effective registration date and the numeric membership level.
        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
        // Alongside the human-readable line, publish an immutable, machine-readable event describing
        // the create: a JSON object stamped with a process-wide monotonically increasing sequence, the
        // owner id, the owner's current primary identifier (the unified memberId) and its numeric
        // membership level.
        Map<String, Object> ownerCreatedEvent = new LinkedHashMap<>();
        ownerCreatedEvent.put("seq", AUDIT_EVENT_SEQ.incrementAndGet());
        ownerCreatedEvent.put("ownerId", owner.getId());
        ownerCreatedEvent.put("memberId", owner.getMemberId());
        ownerCreatedEvent.put("membershipLevel", ownerDto.getMembershipLevel());
        ownerCreatedEvent.put("event", "OWNER_CREATED");
        AUDIT.info(AUDIT_MAPPER.writeValueAsString(ownerCreatedEvent));
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        // Remember the created owner against its idempotency key (when one was supplied) so a later
        // create repeating the same key returns this same owner rather than creating a duplicate.
        if (idempotencyKey != null) {
            idempotentCreations.put(idempotencyKey, ownerDto);
        }
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        currentOwner.setAddress(ownerFieldsDto.getAddress());
        currentOwner.setCity(ownerFieldsDto.getCity());
        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
        currentOwner.setLastName(ownerFieldsDto.getLastName());
        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
        this.clinicService.saveOwner(currentOwner);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        // Soft delete: flag the owner deleted and retain the row rather than removing it, so the
        // owner is still readable via GET afterwards (now carrying 'deleted' true) while the create
        // endpoint's duplicate/identity checks below skip it.
        owner.setDeleted(true);
        this.clinicService.saveOwner(owner);
        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        HttpHeaders headers = new HttpHeaders();
        Pet pet = petMapper.toPet(petFieldsDto);
        owner.setId(ownerId);
        pet.setOwner(owner);
        pet.getType().setName(null);
        this.clinicService.savePet(pet);
        PetDto petDto = petMapper.toPetDto(pet);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
            .buildAndExpand(pet.getId()).toUri());
        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner != null) {
            Pet currentPet = this.clinicService.findPetById(petId);
            if (currentPet != null) {
                currentPet.setBirthDate(petFieldsDto.getBirthDate());
                currentPet.setName(petFieldsDto.getName());
                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
                this.clinicService.savePet(currentPet);
                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Visit visit = visitMapper.toVisit(visitFieldsDto);
        Pet pet = new Pet();
        pet.setId(petId);
        visit.setPet(pet);
        this.clinicService.saveVisit(visit);
        VisitDto visitDto = visitMapper.toVisitDto(visit);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
            .buildAndExpand(visit.getId()).toUri());
        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
    }


    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner != null) {
            Pet pet = owner.getPet(petId);
            if (pet != null) {
                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    /**
     * Read the {@code Idempotency-Key} header from the current request, or {@code null} when the
     * header is absent, blank, or no request is bound to the thread. The header is not part of the
     * generated API signature, so it is read from the ambient request rather than a method parameter.
     */
    private static String currentIdempotencyKey() {
        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
            return null;
        }
        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
        return isBlank(key) ? null : key;
    }

    private static boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }

    /**
     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
     * run of whitespace to a single space, and lower-case. Used so that last name and address are
     * compared case-insensitively with collapsed whitespace.
     */
    private static String collapse(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    /**
     * Common street-type abbreviations expanded during address normalization.
     */
    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
        "ST", "STREET",
        "RD", "ROAD",
        "AVE", "AVENUE");

    /**
     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
     * address maps to itself.
     */
    private static String normalizeAddress(String value) {
        if (value == null) {
            return "";
        }
        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
        }
        return sb.toString();
    }

    /**
     * Derive the stable household identifier shared by owners with the same normalized last name
     * and postcode. It is a deterministic function of those two values, so every member of a
     * household independently derives the same identifier: the first 12 upper-case hex characters
     * of {@code SHA-256(normalizedLastName + '|' + postcode)}. A {@code null} postcode contributes
     * an empty segment.
     */
    private static String householdId(String normalizedLastName, String postcode) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest((normalizedLastName + "|" + (postcode == null ? "" : postcode))
                    .getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.substring(0, 12).toUpperCase();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    /**
     * Derive the identity key into which all duplicate detection is consolidated: the full lower-case
     * hex SHA-256 over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. A
     * null email or last name contributes an empty segment. Two owners are duplicates only when their
     * whole identity keys are equal. Delegates to {@link IdentityKeys#identityKey} so the value here
     * matches the one the mapper exposes on the owner DTO.
     */
    private static String identityKey(String telephone, String email, String lastName) {
        return IdentityKeys.identityKey(telephone, email, lastName);
    }

    /**
     * Count the existing owners that share the given first and last name, compared
     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
     * namesakes that already existed at creation time (the new owner itself is not included).
     */
    private int countNamesakes(String firstName, String lastName) {
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
                && existing.getLastName().equalsIgnoreCase(lastName))
            .count();
    }

    /**
     * Count the existing owners that already belong to the given household (i.e. carry the same
     * non-null householdId). Called after any existing members have been backfilled with the shared
     * identifier but before the new owner is saved, so the returned value reflects the members that
     * already existed at creation time (the new owner itself is not included). Returns 0 when the
     * new owner is not part of any household ({@code householdId} is null).
     */
    private int countHouseholdMembers(String householdId) {
        if (householdId == null) {
            return 0;
        }
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> householdId.equals(existing.getHouseholdId()))
            .count();
    }

    /**
     * Compute the membership-level cap for a new owner joining the given household: one above the
     * current maximum membership level among the existing (non-deleted) members already carrying
     * this household id, using each member's effective (already-capped) level as returned to
     * clients. Returns {@code null} when the household has no existing member, so no cap applies.
     */
    private Integer householdMembershipLevelCap(String householdId) {
        if (householdId == null) {
            return null;
        }
        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
            .filter(existing -> !existing.isDeleted())
            .filter(existing -> householdId.equals(existing.getHouseholdId()))
            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
            .max();
        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
    }

    /**
     * Find an existing owner that this new owner is a possible (soft) duplicate of: one whose
     * {@code soundex(lastName)} and postcode match the new owner's while its identity key differs (so
     * the two are not the same identity, which would already have been rejected as a 409). When
     * several existing owners match, the earliest (lowest id) is returned so the result is
     * deterministic. Returns {@code null} when there is no such owner — including when the new owner
     * has no last name or postcode, since a shared postcode is required to match.
     */
    private Owner findPossibleDuplicate(String lastName, String postcode, String identityKey) {
        if (isBlank(lastName) || isBlank(postcode)) {
            return null;
        }
        String soundex = IdentityKeys.soundex(lastName);
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> !existing.isDeleted())
            .filter(existing -> soundex.equals(IdentityKeys.soundex(existing.getLastName())))
            .filter(existing -> postcode.equals(existing.getPostcode()))
            .filter(existing -> !identityKey.equals(
                identityKey(existing.getTelephone(), existing.getEmail(), existing.getLastName())))
            .min(java.util.Comparator.comparing(Owner::getId))
            .orElse(null);
    }

    /**
     * The maximum number of owners a single city may contain. Once a city holds this many owners a
     * request to create another owner in it is rejected as a conflict.
     */
    private static final int MAX_OWNERS_PER_CITY = 50;

    /**
     * The number of owners a city may already hold before a newly created owner in it is flagged as
     * approaching capacity. Once a city holds this many owners (up to, but not including, the hard
     * limit of {@link #MAX_OWNERS_PER_CITY}), a new owner is flagged with {@code capacityWarning} true.
     */
    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;

    /**
     * Count the existing owners registered in the given city, compared case-insensitively. Called
     * before the new owner is saved, so the returned value reflects the owners that already existed
     * at creation time.
     */
    private int countOwnersInCity(String city) {
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
            .count();
    }

    /**
     * The maximum number of owners that may be created on a single day. Once this many owners
     * already carry a given day's registration date, a request to create another owner that day is
     * rejected with a 429.
     */
    private static final int MAX_OWNERS_PER_DAY = 100;

    /**
     * The number of owners that may be created on a single day before the bulk-signup warning is
     * flagged. Once more than this many owners already carry a given day's registration date, a
     * newly created owner is flagged with {@code bulkSignupWarning} set true.
     */
    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;

    /**
     * Count the existing owners whose registration date is the given day. Called before the new
     * owner is saved, so the returned value reflects the owners that already existed at creation
     * time.
     */
    private int countOwnersRegisteredOn(LocalDate date) {
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> date.equals(existing.getRegistrationDate()))
            .count();
    }

    /** Fixed public holidays the business-day roll skips. */
    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));

    /**
     * Roll a date forward onto a business day: Saturdays, Sundays and listed public holidays are
     * advanced one day at a time until a non-weekend, non-holiday day is reached, while an ordinary
     * business day is returned unchanged. Used so the effective registration date (whether supplied
     * or defaulted) always falls on a business day.
     */
    private static LocalDate toBusinessDay(LocalDate date) {
        while (isWeekendOrHoliday(date)) {
            date = date.plusDays(1);
        }
        return date;
    }

    private static boolean isWeekendOrHoliday(LocalDate date) {
        return switch (date.getDayOfWeek()) {
            case SATURDAY, SUNDAY -> true;
            default -> PUBLIC_HOLIDAYS.contains(date);
        };
    }

    /**
     * Build the unified member id for a new owner: {@code '<REGION><FY><HASH8><CHK>'} where REGION is
     * the region derived from the owner's postcode/city, FY is the 2-digit fiscal year of the
     * (business-day-adjusted) {@code registrationDate}, HASH8 is the first 8 upper-case hex characters
     * of {@code SHA-256(normalizedTelephone + lastName)}, and CHK is a single Luhn check digit (0-9)
     * computed over the digits contained in the {@code '<REGION><FY><HASH8>'} base
     * (e.g. {@code 'NSW261A2B3C4D9'}).
     */
    private static String memberId(String region, LocalDate registrationDate,
                                   String normalizedTelephone, String lastName) {
        String fy = String.format("%02d",
            OwnerMapper.fiscalYearStart(registrationDate) % 100);
        String hash8 = hash8(normalizedTelephone + (lastName == null ? "" : lastName));
        String base = region + fy + hash8;
        return base + luhnCheckDigit(base);
    }

    /**
     * Compute a single Luhn check digit (0-9) over the digit characters contained in {@code value};
     * non-digit characters (e.g. the region's letters or the hex letters of HASH8) are skipped.
     */
    private static int luhnCheckDigit(String value) {
        int sum = 0;
        boolean dbl = true;
        for (int i = value.length() - 1; i >= 0; i--) {
            char c = value.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    /**
     * Ensure the computed member id is unique across existing owners. When {@code base} is already
     * free it is returned unchanged; otherwise {@code '-<n>'} is appended using the smallest {@code n}
     * of 2 or more that produces a value no existing owner already carries.
     */
    private String deduplicateMemberId(String base) {
        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
            .map(Owner::getMemberId)
            .filter(java.util.Objects::nonNull)
            .collect(java.util.stream.Collectors.toSet());
        if (!inUse.contains(base)) {
            return base;
        }
        int n = 2;
        while (inUse.contains(base + "-" + n)) {
            n++;
        }
        return base + "-" + n;
    }

    /**
     * First 8 upper-case hex characters of {@code SHA-256(input)}.
     */
    private static String hash8(String input) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(input.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.substring(0, 8).toUpperCase();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    /**
     * Derive the owner's region, preferring the postcode: look up the region by postcode range first
     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), then fall back to the city-to-region table
     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is absent or in no known
     * range. Returns {@code 'UNKNOWN'} when neither source resolves a region. This mirrors the
     * mapper's locality derivation, so the customer code's region segment and the owner's locality
     * always agree.
     */
    private static String deriveRegion(String postcode, String city) {
        if (postcode != null && postcode.matches("\\d{4}")) {
            int value = Integer.parseInt(postcode);
            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
                int[] range = entry.getValue();
                if (value >= range[0] && value <= range[1]) {
                    return entry.getKey();
                }
            }
        }
        if (city == null) {
            return "UNKNOWN";
        }
        return CITY_REGION.getOrDefault(city, "UNKNOWN");
    }

    /**
     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
     * and accepts any 4-digit postcode.
     */
    private static final Map<String, String> CITY_REGION = Map.of(
        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /**
     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
     * Each entry is a two-element {@code {low, high}} array.
     */
    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
        "NSW", new int[] {2000, 2099},
        "VIC", new int[] {3000, 3099},
        "QLD", new int[] {4000, 4099});

    /**
     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
     * optional and the request contract stays backward-compatible). When supplied it must be exactly
     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
     * 4-digit postcode. A malformed or out-of-range postcode throws an
     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
     */
    private static void validatePostcode(String city, String postcode) {
        if (postcode == null || postcode.isEmpty()) {
            return;
        }
        if (!postcode.matches("\\d{4}")) {
            throw new InvalidOwnerFieldsException(List.of("postcode"));
        }
        String region = city == null ? null : CITY_REGION.get(city);
        if (region == null) {
            return;
        }
        int[] range = REGION_POSTCODES.get(region);
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw new InvalidOwnerFieldsException(List.of("postcode"));
        }
    }

    /**
     * Required national-number length for each E.164 country calling code we validate: a
     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
     */
    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
        "1", 10,
        "61", 9);

    /**
     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
     * {@code '+'} with its country code is preserved; otherwise the Australian country code
     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
     * rejected with a 400.
     */
    private static String toE164(String raw) {
        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
        boolean hasCountryCode = cleaned.startsWith("+");
        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
        if (!digits.matches("\\d+")) {
            throw new InvalidOwnerFieldsException(List.of("telephone"));
        }
        if (!hasCountryCode) {
            if (digits.startsWith("0")) {
                digits = digits.substring(1);
            }
            digits = "61" + digits;
        }
        if (digits.length() < 8 || digits.length() > 15) {
            throw new InvalidOwnerFieldsException(List.of("telephone"));
        }
        // For a recognised country code, the national number (the digits after the code) must be
        // exactly the expected length for that country. Match the longest known code so a shorter
        // code that is a prefix of another cannot mask it.
        for (int codeLength = 3; codeLength >= 1; codeLength--) {
            if (digits.length() <= codeLength) {
                continue;
            }
            String countryCode = digits.substring(0, codeLength);
            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
            if (requiredNationalLength != null) {
                if (digits.length() - codeLength != requiredNationalLength) {
                    throw new InvalidOwnerFieldsException(List.of("telephone"));
                }
                break;
            }
        }
        return "+" + digits;
    }

    /**
     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
     * and a domain with at least one dot-separated label, none of which contain whitespace or
     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
     */
    private static final Pattern EMAIL_PATTERN =
        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");

    /**
     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
     * after the {@code @}, compared case-insensitively) is on this blocklist is rejected with a 400.
     */
    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
        "mailinator.com", "tempmail.com", "guerrillamail.com");

    /**
     * Validate and normalize an optional owner email. Returns {@code null} when no email was
     * supplied (the field is optional). When supplied it must be a syntactically valid address whose
     * domain is not on the disposable-domain blocklist, otherwise an
     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400. A valid
     * address is returned lower-cased.
     */
    private static String normalizeEmail(String email) {
        if (email == null || email.isEmpty()) {
            return null;
        }
        String trimmed = email.trim();
        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
            throw new InvalidOwnerFieldsException(List.of("email"));
        }
        String normalized = trimmed.toLowerCase();
        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
            throw new InvalidOwnerFieldsException(List.of("email"));
        }
        return normalized;
    }
}

